/**
 * Minimal chalk shim — implements the API surface used in clawdbot dist bundles.
 *
 * Supports: bold, dim, italic, gray, red, green, yellow, blue, magenta, cyan,
 * white, *Bright variants, hex(), Chalk class, method chaining, and level.
 *
 * Placed in node_modules instead of inlined per-file because chalk is imported
 * from five separate dist chunks. The clawdbot node_modules directory is tracked
 * in git (see .gitignore: !src-tauri/resources/clawdbot/node_modules/).
 */

function hexToRgb(hex) {
  const m = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
  return m
    ? [parseInt(m[1], 16), parseInt(m[2], 16), parseInt(m[3], 16)]
    : [255, 255, 255];
}

function detectLevel() {
  if (process.env.NO_COLOR) return 0;
  const force = process.env.FORCE_COLOR;
  if (force !== undefined) return Math.min(3, Math.max(0, parseInt(force, 10) || 1));
  if (process.stdout.isTTY || process.stderr.isTTY) return 1;
  return 0;
}

const ANSI_STYLES = {
  bold:          { open: '1',  close: '22' },
  dim:           { open: '2',  close: '22' },
  italic:        { open: '3',  close: '23' },
  underline:     { open: '4',  close: '24' },
  gray:          { open: '90', close: '39' },
  grey:          { open: '90', close: '39' },
  black:         { open: '30', close: '39' },
  red:           { open: '31', close: '39' },
  green:         { open: '32', close: '39' },
  yellow:        { open: '33', close: '39' },
  blue:          { open: '34', close: '39' },
  magenta:       { open: '35', close: '39' },
  cyan:          { open: '36', close: '39' },
  white:         { open: '37', close: '39' },
  blackBright:   { open: '90', close: '39' },
  redBright:     { open: '91', close: '39' },
  greenBright:   { open: '92', close: '39' },
  yellowBright:  { open: '93', close: '39' },
  blueBright:    { open: '94', close: '39' },
  magentaBright: { open: '95', close: '39' },
  cyanBright:    { open: '96', close: '39' },
  whiteBright:   { open: '97', close: '39' },
};

class Chalk {
  constructor(options = {}) {
    this.level = typeof options.level === 'number' ? options.level : detectLevel();
    this._stack = [];
    return _makeProxy(this);
  }

  _clone(extra) {
    const c = Object.create(Chalk.prototype);
    c.level = this.level;
    c._stack = [...this._stack, extra];
    return _makeProxy(c);
  }

  _apply(text) {
    const s = String(text);
    if (this.level === 0 || this._stack.length === 0) return s;
    const open = this._stack.map(c => `\x1b[${c.open}m`).join('');
    const close = this._stack.slice().reverse().map(c => `\x1b[${c.close}m`).join('');
    return `${open}${s}${close}`;
  }

  hex(color) {
    const [r, g, b] = hexToRgb(color);
    const child = this._clone({ open: `38;2;${r};${g};${b}`, close: '39' });
    // hex() returns a plain function (not further chainable in this codebase)
    return (text) => child._apply(text);
  }
}

function _makeProxy(instance) {
  return new Proxy(instance, {
    get(target, prop) {
      // Own properties / prototype methods take priority
      if (prop === 'level') return target.level;
      if (prop === 'hex') return (color) => target.hex(color);
      if (prop === '_apply' || prop === '_clone' || prop === '_stack') return target[prop].bind ? target[prop].bind(target) : target[prop];

      if (Object.prototype.hasOwnProperty.call(ANSI_STYLES, prop)) {
        const child = target._clone(ANSI_STYLES[prop]);
        // Return a function that is also proxied so it supports further chaining
        const fn = (text) => child._apply(text);
        return new Proxy(fn, {
          get(fnTarget, fnProp) {
            if (fnProp === 'hex') return (color) => child.hex(color);
            if (Object.prototype.hasOwnProperty.call(ANSI_STYLES, fnProp)) {
              const grandchild = child._clone(ANSI_STYLES[fnProp]);
              const gfn = (text) => grandchild._apply(text);
              return new Proxy(gfn, {
                get(gfnTarget, gfnProp) {
                  if (gfnProp === 'hex') return (color) => grandchild.hex(color);
                  return gfnTarget[gfnProp];
                },
              });
            }
            return fnTarget[fnProp];
          },
        });
      }

      return target[prop];
    },
    apply(target, _thisArg, args) {
      return target._apply(args[0]);
    },
  });
}

const chalk = new Chalk();

export { Chalk };
export default chalk;
